html:
{% set f = sacco_customer_file(doc.name) %}
{% if f %}
{% include "sacco_manager/templates/print/member_file.html" %}
{% else %}
<div style="font-family:Arial;font-size:11px">
<h2 style="color:#1a3c2e">{{ doc.customer_name }}</h2>
<p>This customer is not linked to a SACCO member, so there is no member file. Link the customer to its SACCO Member record (SACCO Member &rarr; Customer field) and reprint.</p>
<table style="width:100%">
<tr><td>Customer ID</td><td><b>{{ doc.name }}</b></td></tr>
<tr><td>Group</td><td>{{ doc.customer_group or "" }}</td></tr>
<tr><td>Mobile</td><td>{{ doc.mobile_no or "" }}</td></tr>
<tr><td>Email</td><td>{{ doc.email_id or "" }}</td></tr>
<tr><td>Tax ID</td><td>{{ doc.tax_id or "" }}</td></tr>
</table>
</div>
{% endif %}
